save(418,dict(paragraphs=['Sarbani Chakravarti is an educator, poet and prose writer. Her IPPL Journal biography records postgraduate study in English and business administration, alongside teaching in Kolkata. She contributes poetry and literary criticism, and her fiction is included in “The Virasat Anthology of Short Stories”, edited by Nishi Pulugurtha and published by Blue Pencil.','In “Circumspection”, fear is asked to guard a deserted castle against hope. Darkness offers a troubling refuge, while light promises movement but also exhaustion and collapse. The poem reverses the usual comfort of hopeful imagery, allowing its guarded speaker to expose the cost of both expectation and withdrawal.'],books=[dict(title='The Virasat Anthology of Short Stories',detail='Contributor. Edited by Nishi Pulugurtha; Blue Pencil.',url='https://www.bluepencilpublishers.com/book/the-virasat-anthology-of-short-stories/')],sources=[source('IPPL Journal — Sarbani Chakravarti','https://ippljournal.org/issue-6-april-2025/sarbani-chakravarti/','Search-indexed complete contributor note: dual master’s degrees, Kolkata teaching, poetry and prose; matches distinctive captured qualifications. Direct open failed.','search_index'),source('Blue Pencil — The Virasat Anthology of Short Stories','https://www.bluepencilpublishers.com/book/the-virasat-anthology-of-short-stories/','Publisher search-indexed contributor list explicitly includes Sarbani Chakravarti; Nishi Pulugurtha is editor. Direct open failed.','search_index'),source('Saaranga — Deeply Intimate and Universal at Once','https://magazine.saarangabooks.com/deeply-intimate-and-universal-at-once/','Search-indexed review by Sarbani Chakravarti with educator/poet/author/IPPL member biography, dated 15 August 2026. Supports literary criticism.','search_index')],identity_match='IPPL biography repeats distinctive English and business-administration degrees and teaching background from local capture. Saaranga connects same full name, educator/poet role and IPPL membership; publisher lists same literary contributor.',poems_read=[dict(id=623,title='Circumspection',coverage='All four original English stanzas read.',basis='Fear gatekeeper, hope as danger, empty castle and unlit creatures, torchlit dancing followed by exhaustion, final disappearance. Not interpreted as a diagnosis or personal mental-health disclosure.')],limitations=['Outside pages were available through search indexing; direct journal/publisher opens failed and access limitation remains explicit.','Virasat is an anthology contribution, not a sole-authored book; no date or ISBN inferred.','Earlier corporate sectors and Zurich teaching preserved in captured biography but not newly asserted without outside confirmation.','No specific current school or length of service asserted.'],research_leads=[dict(url='https://sbgskolkata.ac.in/sites/subgs/files/inline-images/List%20of%20teachers%20with%20Qualification_2425%20%281%29.pdf',finding='Indexed school list names Sarbani Chakravarti with M.A./B.Ed. but not literary profile; not needed to name an employer.'),dict(url='https://www.hashtagkalakar.net/post/the-diary-of-a-footloose-free-bird-chapter-1-the-exposition',finding='Indexed prose by same name; first-person narrator’s personal circumstances not converted into author biography.'),dict(url='https://bookshop.org/p/books/the-story-project-15-stories-and-poems-of-levellers-tell-me-your-story/2b7f53d41b28fdc3?ean=9798268774382',finding='Indexed anthology contributor list includes same name; selective shelf uses publisher-verified Virasat rather than every possible contribution.')],next_action='Independent author/editor review and, if desired, direct publisher page/title-page confirmation when accessible.'))
